def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            if math.isfinite(x):
                y.append(x)
        except Exception:
            pass
    if not y:
        return [0.0] * horizon
    n = len(y)

    def median(a):
        b = sorted(a)
        m = len(b)
        return b[m // 2] if m % 2 else 0.5 * (b[m // 2 - 1] + b[m // 2])

    def one_fold(train, lag, steps):
        anchor = min(16, lag, len(train) - lag)
        if anchor < 3:
            return [train[-1]] * steps
        offsets = [train[-anchor + i] - train[-anchor + i - lag] for i in range(anchor)]
        shift = median(offsets)
        return [train[len(train) - lag + k] + shift for k in range(steps)]

    candidates = []
    for lag in range(180, 231):
        errors = []
        for back in (24, 48, 72):
            cut = n - back
            if cut <= lag + 16 or cut + 24 > n:
                continue
            pred = one_fold(y[:cut], lag, 24)
            for j, f in enumerate(pred):
                a = y[cut + j]
                errors.append(2.0 * abs(f - a) / (abs(f) + abs(a) + 1e-9))
        if errors:
            candidates.append((sum(errors) / len(errors), lag))
    if not candidates:
        return [y[-1]] * horizon
    _, lag = min(candidates)
    out = []
    extended = y[:]
    anchor = min(16, lag, n - lag)
    shift = median([y[-anchor + i] - y[-anchor + i - lag] for i in range(anchor)]) if anchor >= 3 else 0.0
    for _ in range(horizon):
        idx = len(extended) - lag
        value = extended[idx] + shift if idx >= 0 else extended[-1]
        out.append(value)
        extended.append(value)
    return out

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            if math.isfinite(x):
                y.append(x)
        except Exception:
            pass
    if not y:
        return [0.0] * horizon

    def motion(train, steps, window, damping):
        a = train[-min(window, len(train)):]
        if len(a) < 5:
            return [a[-1]] * steps
        d = [a[i] - a[i - 1] for i in range(1, len(a))]
        q = [d[i] - d[i - 1] for i in range(1, len(d))]
        slope = sum(d[-min(8, len(d)):]) / min(8, len(d))
        curve = sum(q[-min(12, len(q)):]) / min(12, len(q)) if q else 0.0
        level = a[-1]
        out = []
        velocity = slope
        for k in range(1, steps + 1):
            velocity = damping * velocity + (damping ** k) * curve
            level += velocity
            out.append(level)
        return out

    n = len(y)
    choices = []
    for window in (16, 24, 32, 48):
        for damping in (0.94, 0.97, 0.985):
            for weight in (0.25, 0.5, 0.75, 1.0):
                errors = []
                for back in (12, 24, 36, 48):
                    cut = n - back
                    if cut < window or cut + 12 > n:
                        continue
                    raw = motion(y[:cut], 12, window, damping)
                    base = y[cut - 1]
                    pred = [base + weight * (v - base) for v in raw]
                    for j, f in enumerate(pred):
                        a = y[cut + j]
                        errors.append(2.0 * abs(f - a) / (abs(f) + abs(a) + 1e-9))
                if errors:
                    choices.append((sum(errors) / len(errors), window, damping, weight))
    if not choices:
        return [y[-1]] * horizon
    _, window, damping, weight = min(choices)
    raw = motion(y, horizon, window, damping)
    base = y[-1]
    return [base + weight * (v - base) for v in raw]
